package edu.cybertrace;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.beans.factory.annotation.Value; import java.nio.file.*; import java.security.*; import java.time.Instant; import java.nio.charset.StandardCharsets;
@Service class ForensicsService {
 // Keep integrity operations in one place so upload, verification, and the scheduled watcher use the same hash rules.
 final AuditRepo audits; final AlertRepo alerts; final EvidenceRepo evidence; final CustodyRepo custody; final VerificationRepo verifications; final EvidenceVersionRepo versions;
 @Value("${cybertrace.storage:../storage/evidence}") String storageDirectory;
 ForensicsService(AuditRepo a,AlertRepo al,EvidenceRepo e,CustodyRepo c,VerificationRepo v,EvidenceVersionRepo versions){audits=a;alerts=al;evidence=e;custody=c;verifications=v;this.versions=versions;}
 String expectedHash(Evidence item){return versions.findByEvidenceIdOrderByVersionNumberDesc(item.id).stream().findFirst().map(v->v.sha256).orElse(item.referenceHash);}
 static String hash(Path p)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(p)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)d.update(b,0,n);}return hex(d.digest());}
 static String hex(byte[] b){var s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v));return s.toString();}
 // Each record points to the previous hash. Millisecond timestamps round-trip consistently through SQLite.
 @Transactional synchronized void audit(String actor,String action,String target,String outcome,String details){AuditEntry x=new AuditEntry();x.at=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS);x.actor=actor;x.action=action;x.target=target;x.outcome=outcome;x.details=details;x.previousHash=audits.findTopByOrderByIdDesc().map(a->a.entryHash).orElse("0".repeat(64));String canonical=auditCanonical(x.at,x.actor,x.action,x.target,x.outcome,x.details,x.previousHash);try{x.entryHash=hex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}audits.saveAndFlush(x);}
 static String auditCanonical(Instant at,String actor,String action,String target,String outcome,String details,String previousHash){return String.join("|",at.truncatedTo(java.time.temporal.ChronoUnit.MILLIS).toString(),safe(actor),safe(action),safe(target),safe(outcome),safe(details),previousHash);} static String safe(String s){return s==null?"":s.replace("|","/");}
 void alert(String severity,String reason,Long id,String actor,String owner){AlertRecord a=new AlertRecord();a.severity=severity;a.reason=reason;a.evidenceId=id;a.actor=actor;a.owner=owner;a.createdAt=Instant.now();alerts.save(a);}
 @Scheduled(fixedDelay=30000,initialDelay=15000) @Transactional public void watchEvidenceFiles(){Path root=Path.of(storageDirectory).toAbsolutePath().normalize();for(Evidence e:evidence.findAll()){String expected=expectedHash(e),observed,status;try{observed=hash(root.resolve(e.storageName));status=expected.equals(observed)?"INTACT":"MODIFIED";}catch(Exception ex){observed="";status="VERIFICATION_ERROR";}boolean newObservation=!status.equals(e.lastIntegrityStatus)||!observed.equals(e.lastObservedHash);e.lastObservedHash=observed;e.lastIntegrityStatus=status;e.lastCheckedAt=Instant.now();evidence.save(e);if(!newObservation||"INTACT".equals(status))continue;String actor="SYSTEM_WATCHER";Verification v=new Verification();v.evidenceId=e.id;v.actor=actor;v.referenceHash=e.referenceHash;v.currentVersionHash=expected;v.observedHash=observed;v.status=status;v.createdAt=e.lastCheckedAt;verifications.save(v);audit(actor,"EVIDENCE_INTEGRITY_WATCH",e.evidenceNo,status,"Original="+e.referenceHash+"; expected current version="+expected+"; observed="+observed);alert("HIGH","Automatic file monitor detected "+status.toLowerCase()+" for "+e.evidenceNo,e.id,actor,e.registeredBy);}}
}
